  perform public.authored_ai_qualify(p_ref => v_ref, p_role => $vf$guided_practice$vf$, p_axes => $vf${"A":{"state":"pass"},"B":{"state":"pass"},"C":{"state":"pass"},"D":{"state":"pass"},"E":{"state":"not_applicable"},"F":{"state":"pass"},"G":{"state":"not_applicable"},"H":{"state":"pass"}}$vf$::jsonb, p_annotation_ref => $vf$authored-central-meaning-r5-cm-guided-1.v3$vf$, p_evidence_ids => array['ai_decision:' || v_decision, $vf$ai_receipt:682dfbd97fa8c2317315f3458d11d24033364afee980d78331c03da5563e2846$vf$, $vf$js_gold:fd779eb465c83a3eb78f2fed06fe708e9e3ea5bb80315921f78acdd28ac92a18$vf$, 'rights:first_party_original_declaration', $vf$h_probe:gold_response_graded_correct$vf$]);
  v_ref := public.authored_item_register(p_ref => $vf$authored:r5-cm-ind-2$vf$, p_task => $vf$r.central_meaning$vf$, p_task_key => $vf$authored-central-meaning$vf$, p_role_class => $vf$assessment$vf$, p_intended_role => $vf$independent_check$vf$, p_group => $vf$r5cm-i2$vf$, p_body => $vf${"sentences":["Relying on turn-by-turn directions may be weakening our ability to understand the places we live in.","When a device tells us where to turn, we no longer need to build a mental picture of how streets connect.","Following these instructions can leave a driver with less knowledge of how the parts of a route fit together.","Some people argue that this hardly matters, since the device is always available.","But devices fail, batteries die, and signals disappear, and a person with no sense of direction is then truly lost.","Moreover, finding our own way requires us to attend to landmarks and their connections."],"stem":"다음 글의 요지로 가장 적절한 것은?","choices":["길 안내 기기는 운전자의 안전을 높여 준다.","스스로 길을 찾지 않으면 주변 공간을 이해하는 힘이 줄어들 수 있다.","배터리와 신호 문제 때문에 길 안내 기기는 믿을 수 없다.","기억력을 높이려면 지도를 직접 그려 보아야 한다.","기기는 늘 쓸 수 있으므로 방향 감각은 중요하지 않다."]}$vf$::jsonb, p_gold => $vf${"answer":1,"claim":0,"claimRestated":[],"support":[1,2,4,5],"supportDisputed":[],"opposed":[3],"relationProbe":{"sentence":3,"relation":"opposed"},"gist":"길 안내 기기에 기대면 우리가 사는 곳을 이해하는 능력이 약해질 수 있다.","distractors":[{"choice":0,"design":"off_text","why":"안전은 글에 나오지 않는다."},{"choice":2,"design":"too_narrow","why":"반론을 반박하는 근거 하나(5번)만 옮기고 ‘믿을 수 없다’로 단정해 과장했다."},{"choice":3,"design":"off_text","why":"글은 지도를 직접 그리라는 방법이나 일반 기억력 향상이라는 목표를 제시하지 않는다. 길 안내 의존과 공간 이해에 관한 논의를 글에 없는 처방으로 바꿨다."},{"choice":4,"design":"opposed_view","why":"필자가 반박하는 생각(4번)이다."}]}$vf$::jsonb, p_annotation_ref => $vf$authored-central-meaning-r5-cm-ind-2.v3$vf$, p_provenance => $vf${"author":"Claude Opus 5.5 (Claude Code agent, Vocaflow FINAL session)","method":"Vocaflow 자체 창작 — 기출 지문을 옮기거나 고쳐 쓰지 않았다. 평가원 문항의 '형식'(요지·제목·주제 5지선다)만 따랐다.","derivedFrom":[],"createdAt":"2026-1