  v_ref := public.authored_item_register(p_ref => $vf$authored:r5-cm-transfer-1$vf$, p_task => $vf$r.central_meaning$vf$, p_task_key => $vf$authored-central-meaning$vf$, p_role_class => $vf$assessment$vf$, p_intended_role => $vf$transfer$vf$, p_group => $vf$r5cm-x1$vf$, p_body => $vf${"sentences":["Imagine a group of shoppers who trust a drink more after seeing the word \"natural\" on its label.","They treat the word as if it guaranteed that the drink were healthier or safer.","The word alone, however, does not describe which ingredients are inside the drink.","The imagined drink could still contain a long list of sweeteners and additives.","The word, in short, tells buyers far less than they believe it does.","Reading the list of ingredients is a much more reliable way to judge what is inside the package."],"stem":"다음 글의 제목으로 가장 적절한 것은?","choices":["Why Shoppers Should Avoid Natural Foods","The Empty Promise of the \"Natural\" Label","How Additives Make Drinks Sweeter","Reading Ingredients: The Key to Healthy Eating","Natural or Artificial: Which Food Is Safer?"]}$vf$::jsonb, p_gold => $vf${"answer":1,"claim":4,"claimRestated":[],"support":[2,3],"supportDisputed":[0,5],"opposed":[1],"relationProbe":{"sentence":3,"relation":"example"},"gist":"'natural' 표시는 소비자가 믿는 것보다 훨씬 적은 것을 알려 준다.","distractors":[{"choice":0,"design":"distorted","why":"표시를 믿지 말라는 글을 자연식품을 피하라는 주장으로 넘겨 확대했다."},{"choice":2,"design":"off_text","why":"글은 가상의 음료에 감미료와 첨가물이 들어갈 수 있다고 예를 들지만, 첨가물이 음료를 달게 만드는 과정은 설명하지 않는다."},{"choice":3,"design":"too_narrow","why":"성분표 읽기는 마지막의 후속 조언이며 글 전체의 중심인 표시의 정보 한계를 대신하지 못한다. 건강한 식사 전반의 열쇠라는 제목은 본문의 범위도 넘어선다."},{"choice":4,"design":"off_text","why":"글은 자연식품과 인공식품의 안전성을 비교하지 않는다 — 표시의 의미를 따질 뿐이다(소재는 같지만 질문이 다르다)."}]}$vf$::jsonb, p_annotation_ref => $vf$authored-central-meaning-r5-cm-transfer-1.v3$vf$, p_provenance => $vf${"author":"Claude Opus 5.5 (Claude Code agent, Vocaflow FINAL session)","method":"Vocaflow 자체 창작 — 기출 지문을 옮기거나 고쳐 쓰지 않았다. 평가원 문항의 '형식'(요지·제목·주제 5지