  v_ref := public.authored_item_register(p_ref => $vf$authored:opt-transfer-2$vf$, p_task => $vf$e.option_correspondence$vf$, p_task_key => $vf$authored-option-match$vf$, p_role_class => $vf$assessment$vf$, p_intended_role => $vf$transfer$vf$, p_group => $vf$opt-t9$vf$, p_body => $vf${"format":"option_correspondence","sentences":["The Orlen Ice Run is a fictional sled race held each February on a frozen river in the north.","Teams of two pull a wooden sled for twenty kilometers instead of riding on it.","Sleds must be built by the teams themselves, and metal runners are not permitted.","The race was first held in 1962 as a way to test whether the river ice was safe for winter travel.","If the ice is thinner than thirty centimeters, the race is moved to a nearby lake.","The winning team receives no prize money, only a carved wooden spoon."],"stem":"다음 글의 내용과 일치하는 것은?","choices":["두 사람이 한 팀이 되어 썰매를 타고 20킬로미터를 달린다.","팀은 금속 날을 단 썰매를 사용해야 한다.","우승팀은 상금과 함께 나무 숟가락을 받는다.","처음에는 강 얼음이 겨울 이동에 안전한지 시험하려고 열렸다.","얼음이 얇으면 그해 경주는 취소된다."]}$vf$::jsonb, p_gold => $vf${"answer":3,"options":[{"verdict":"reversed","sentence":1,"why":"2번 문장은 썰매를 타는 대신 끈다고 했다 — 탄다는 것은 반대다."},{"verdict":"reversed","sentence":2,"why":"3번 문장은 금속 날이 허용되지 않는다고 했다."},{"verdict":"reversed","sentence":5,"why":"6번 문장은 상금 없이 나무 숟가락만 준다고 했다."},{"verdict":"matches","sentence":3,"why":"4번 문장: 1962년 강 얼음이 겨울 이동에 안전한지 시험하려고 처음 열렸다."},{"verdict":"distorted","sentence":4,"why":"5번 문장은 얼음이 얇으면 근처 호수로 장소를 옮긴다고 했다 — 취소로 바꿨다."}]}$vf$::jsonb, p_annotation_ref => $vf$authored-option-match-opt-transfer-2.v1$vf$, p_provenance => $vf${"author":"Claude (Claude Code agent, Vocaflow FINAL session)","method":"Vocaflow 자체 창작 — 기출 지문을 옮기거나 고쳐 쓰지 않았다","derivedFrom":[],"createdAt":"2026-10-18","humanGold":"pending — 사람 Gold 확정 전","rights":"pending — 사람 원저작 확인 전","set":"e-option-correspondence.v1","item":"opt-transfer-2"}$vf$::jsonb);
