declare v_receipt jsonb := $vf${"schema":"vocaflow.ai-authored-review-receipt/1","set":"v-contextual-sense.v1","source_file_sha256":"fb8bfaeba6461a2cf94ae65d22c95240c88e9a283f72f2bfaca840c5c3026ddb","scope":["vcs-ind-2"],"items":[{"id":"vcs-ind-2","role":"independent_check","item_canonical_sha256":"792de914df3ddccad6957a3f101d3affa688da3a09b013c89ee67eb164633712","body_canonical_sha256":"bbb0d56d6079782a0d24aa3366879cc0c5b12bc0fb1b3e1d7a9d71f73bb06d8a","gold_canonical_sha256":"d9bb19d3ca7cb98a00c78c69765542f811bf6dfb43fc4ab711e2343a282e47d5"}],"reviews":[{"agent":"claude","session_id":"63216a01-12c1-4ea1-9f3a-51ea8e2afb9a","request_id":"63216a01-12c1-4ea1-9f3a-51ea8e2afb9a","prompt_sha256":"4fbd2f33a5b48259db62b38cbe737d3b4db7f8231c668c26758caa8dd9cffc5f","response_sha256":"e55f698fa18f30de92b7bdf1a2f1fdc1af023ce35c6ba8cc4ddaa168a25e12d6","source_file_sha256":"fb8bfaeba6461a2cf94ae65d22c95240c88e9a283f72f2bfaca840c5c3026ddb","verdict":"accept","items":[{"id":"vcs-ind-2","verdict":"accept","choice_0based":4,"gold_issues":[],"why":"In sentence index 3, 'a promise to address unemployment directly' means to deal with or take action on a problem. Sentence index 4 confirms this: within a year the council opened a training center and attracted companies. Sentence index 2 contrasts this with only describing the problem. So '대처하다' (index 4) is the only correct answer. Each distractor is clearly wrong for the reason given. '연설하다' (to give a speech) does not take unemployment as its object. '말을 걸다' (to speak to someone) needs a person as its object. '글로 기록하다' (to write down) is a lure based on the earlier reports, and the critics' line in 1-based sentence 3 rejects mere description. '외면하다' (to ignore) is the opposite of the promise carried out in 1-based sentence 5. The explanations' prose sentence references (2번, 3번, 5번) follow the file's 1-based proseNumbering and match the passage. The gold cue indexes [2,3,4] are 0-based and correct. The English is natural and suitable for high-school learners. The Korean glosses are accurate. There are no untraceable factual claims: the passage is a generic, clearly invented scenario."}]},{"agent":"codex","session_id":"01a16726-b7ac-7502-9f6d-5c816d6809a4","request_id":"006060ae-050e-4f0c-8545-dbe3892f7c96","prompt_sha256":"4fbd2f33a5b48259db62b38cbe737d3b4db7f8231c668c26758caa8dd9cffc5f","response_sha256":"1738fb7db4ab64ce1d74d0c826b7d4fc8b935676507dc2ff9785bc679b6227f3","source_file_sha256":"fb8bfaeba6461a2cf94ae65d22c95240c88e9a283f72f2bfaca840c5c3026ddb","verdict":"accept","items":[{"id":"vcs-ind-2","verdict":"accept","choice_0based":4,"gold_issues":[],"why":"'address unemployment directly'는 실업 문제에 직접 대처한다는 뜻이며, 훈련 센터 개설과 기업 유치가 이를 뒷받침한다. 정답은 4번으로 유일하다. 나머지 선택지와 오답 설명은 문맥에 부합하며, 설명의 문장 번호는 proseNumbering의 1-based 표기와 일치한다. 영어와 한국어는 자연스럽고 학습 수준에 적절하며, 출처 확인이 필요한 실제 연구 결과를 주장하지 않는다."}]}],"judgment":"accepted_candidate_content_and_gold","rights_basis":"first_party_original_declaration_only","rights_grant":false,"human_review_claimed":false,"not_reviewed":["vcs-teach-1","vcs-guided-1","vcs-ind-1","vcs-transfer-1","vcs-delayed-1","vcs-ind-3","vcs-ind-4","vcs-transfer-2"]}$vf$::jsonb; v_ref text; v_decision uuid;
begin
  v_ref := public.authored_item_register(p_ref => $vf$authored:vcs-ind-2$vf$, p_task => $vf$v.contextual_sense$vf$, p_task_key => $vf$authored-vocab-context$vf$, p_role_class => $vf$assessment$vf$, p_intended_role => $vf$independent_check$vf$, p_group => $vf$vcs-t4$vf$, p_body => $vf${"format":"contextual_sense","sentences":["When a town's only factory closed, many residents expected the local government to act quickly.","Instead, officials spent months writing reports that described the situation in great detail.","Critics argued that describing a problem is not the same as solving it.","Finally, a new council was elected with a promise to address unemployment directly.","Within a year it had opened a training center and attracted two smaller companies to the area.","Residents still debate whether the earlier reports helped or merely delayed this progress."],"target":{"sentence":3,"word":"address"},"stem":"밑줄 친 낱말 'address'의 이 글에서의 뜻으로 가장 적절한 것은?","choices":["연설하다","말을 걸다","글로 기록하다","외면하다","대처하다"]}$vf$::jsonb, p_gold => $vf${"answer":4,"cue":[2,3,4],"senseGloss":"(문제·과제에) 착수하여 대처하다","distractors":[{"choice":0,"design":"basic_meaning","why":"'연설하다'는 address 의 익숙한 뜻이지만 실업을 상대로 연설한다는 것은 맥락에 맞지 않는다."},{"choice":1,"design":"collocation_mismatch","why":"'말을 걸다'는 사람을 목적어로 받을 때의 뜻으로, unemployment 같은 문제와 결합하지 않는다."},{"choice":2,"design":"nearby_word","why":"앞의 reports(2번)에 끌린 뜻으로, 3번은 기술만 하는 것을 오히려 비판한다."},{"choice":3,"design":"opposite_sense","why":"직접 대처하겠다는 약속(5번에서 실행)과 정반대다."}]}$vf$::jsonb, p_annotation_ref => $vf$authored-vocab-context-vcs-ind-2.v1$vf$, p_provenance => $vf${"author":"Claude (Claude Code agent, Vocaflow FINAL session)","method":"Vocaflow 자체 창작 — 기출 지문을 옮기거나 고쳐 쓰지 않았다","derivedFrom":[],"createdAt":"2026-10-18","humanGold":"pending — 사람 Gold 확정 전","rights":"pending — 사람 원저작 확인 전","set":"v-contextual-sense.v1","item":"vcs-ind-2"}$vf$::jsonb);
  v_decision := public.content_ai_decision_record(p_ref => v_ref, p_receipt => v_receipt);
  perform public.authored_ai_qualify(p_ref => v_ref, p_role => $vf$independent_check$vf$, p_axes => $vf${"A":{"state":"pass"},"B":{"state":"pass"},"C":{"state":"pass"},"D":{"state":"not_applicable"},"E":{"state":"pass"},"F":{"state":"pass"},"G":{"state":"not_applicable"},"H":{"state":"pass"}}$vf$::jsonb, p_annotation_ref => $vf$authored-vocab-context-vcs-ind-2.v1$vf$, p_evidence_ids => array['ai_decision:' || v_decision, $vf$ai_receipt:fb8bfaeba6461a2cf94ae65d22c95240c88e9a283f72f2bfaca840c5c3026ddb$vf$, $vf$js_gold:d9bb19d3ca7cb98a00c78c69765542f811bf6dfb43fc4ab711e2343a282e47d5$vf$, 'rights:first_party_original_declaration', $vf$h_probe:gold_response_graded_correct$vf$]);
end $do$;

