do $do$
declare v_receipt jsonb := $vf${"schema":"vocaflow.ai-authored-review-receipt/1","set":"r-reference.v1","source_file_sha256":"6807473e00f86c456b6500ca8007bc5e497196dc2f1930183d25d6024f5f5ecf","scope":["ref-teach-1"],"items":[{"id":"ref-teach-1","role":"model_explanation","item_canonical_sha256":"4ecaf2c8c0e217d89c41eef8c784a377804983e545c68944136048a39616bf7e","body_canonical_sha256":"d7e948e268f165497f9d07733b44fcc9e80bca88e7f29f4c504ab2c0c5b0cc1e","gold_canonical_sha256":"b801af6f648c3cda69d5d4fbbdf291ba7207f8972a8eec16fe115c3d0e0a249f"}],"reviews":[{"agent":"claude","session_id":"492cc03e-a04c-4a98-ab05-ab11074f2a71","request_id":"492cc03e-a04c-4a98-ab05-ab11074f2a71","prompt_sha256":"686bf73d16c4c6a6bcc0b26be4afdcf8bc8cec2b46a6103fffcd708c24d414be","response_sha256":"18b5324d3fa5233a87104fde3e9b931dcd0755a4b32a93562bb63f23ac4bb20c","source_file_sha256":"6807473e00f86c456b6500ca8007bc5e497196dc2f1930183d25d6024f5f5ecf","verdict":"accept","items":[{"id":"ref-teach-1","verdict":"accept","choice_0based":1,"gold_issues":[],"why":"Gold answer 1 is correct. Sentence 4 (index 3) introduces a new action, planting a mix of slower, longer-lived species. Sentence 5 (index 4) calls it 'this practice' and criticises it for leaving streets bare for nearly a decade. That criticism only fits slow growth. Sentence 6 (index 5) supports the same reading with its 'tree which survives eighty years'. Every distractor is wrong for the stated reason. Choice 0 is the old fast-growth practice from sentence 1, which would not leave streets bare. Choice 3 is the quick-shade effect from sentence 2, the opposite of the criticism. Choices 2 and 4 reuse words from the storm damage in sentence 3 to make actions the passage never mentions. The 'sentences' arrays in the teach steps are 0-based and match the 1-based sentence numbers in the Korean text. Step 1's point that 'wind' is a noun and not an action is accurate. The passage contains only general, opinion-framed claims and presents no traceable real-world findings. The English is natural and fits Korean high-school level, and the Korean explanations are accurate."}]},{"agent":"codex","session_id":"01a16726-f489-7eb0-9399-b12426aba477","request_id":"27dbd352-7efe-435c-9e4b-64f63c1e1023","prompt_sha256":"686bf73d16c4c6a6bcc0b26be4afdcf8bc8cec2b46a6103fffcd708c24d414be","response_sha256":"edc89adfa64ce4877c1b3baeb4cd76ed3ad22c11904deeecf0a5a2d1bee8773c","source_file_sha256":"6807473e00f86c456b6500ca8007bc5e497196dc2f1930183d25d6024f5f5ecf","verdict":"accept","items":[{"id":"ref-teach-1","verdict":"accept","choice_0based":1,"gold_issues":[],"why":"‘this practice’는 바로 앞 문장의 느리게 자라고 오래 사는 여러 수종을 섞어 심는 행위를 가리키므로 정답은 유일하게 ②이다. ①④는 빠른 성장을 추구한 이전 방식이고, ③⑤는 본문에 제시되지 않은 행위이므로 오답 설명도 타당하다. 결정 근거와 보조 근거의 인덱스가 적절하며, 교수 설명과 한국어 해설은 본문에 부합한다. 영어는 학습 수준에 적절하고, 80년간의 그늘 비교도 지지자들의 주장으로 명시되어 있다."}]}],"judgment":"accepted_candidate_content_and_gold","rights_basis":"first_party_original_declaration_only","rights_grant":false,"human_review_claimed":false,"not_reviewed":["ref-guided-1","ref-ind-1","ref-ind-2","ref-transfer-1","ref-delayed-1","ref-ind-3","ref-ind-4","ref-transfer-2"]}$vf$::jsonb; v_ref text; v_decision uuid;
begin
  v_ref := public.authored_item_register(p_ref => $vf$authored:ref-teach-1$vf$, p_task => $vf$r.reference$vf$, p_task_key => $vf$authored-reference$vf$, p_role_class => $vf$instruction$vf$, p_intended_role => $vf$model_explanation$vf$, p_group => $vf$ref-t1$vf$, p_body => $vf${"format":"choice_evidence","sentences":["City planners once chose street trees mainly for how quickly they grew.","Fast-growing species filled empty sidewalks within a few years, which pleased residents who wanted shade.","However, many of these trees had weak wood and shallow roots, so storms often brought them down onto cars and power lines.","Some cities have therefore begun planting a mix of slower species that live longer and resist wind.","Critics complain that this practice leaves streets looking bare for nearly a decade.","Supporters reply that a tree which survives eighty years provides far more shade over its life than two or three quick replacements ever could.","In their view, patience at the start is the price of a canopy that lasts for generations."],"stem":"밑줄 친 'this practice'가 가리키는 대상으로 가장 적절한 것은?","choices":["choosing street trees for their rapid growth","planting a mix of slow, long-lived species","clearing fallen trees from cars and power lines","filling empty sidewalks with shade very quickly","strengthening shallow roots against heavy storms"],"teach":[{"step":"지시어의 단서 읽기","text":"'this practice'는 5번 문장에 있다. 'this'는 바로 앞에서 말한 '행위'를 받고, 비판의 내용(거리가 10년 가까이 휑해 보인다)이 그 행위의 성격을 알려 준다. 가장 가까운 명사 'wind'(4번 끝)는 행위가 아니므로 후보가 아니다.","sentences":[4,3]},{"step":"결정 근거 찾기","text":"4번 문장이 처음으로 '느리게 자라는 수종을 섞어 심는' 새 행위를 꺼낸다. 느리게 자라니 처음 몇 년은 거리가 비어 보인다는 5번의 비판과 정확히 이어진다. 4번이 결정 문장이다.","sentences":[3]},{"step":"정답 설계","text":"정답 ②는 4번의 'planting a mix of slower species that live longer'를 짧게 바꿔 썼다. 6번의 '80년 사는 나무'도 같은 대상을 다시 가리키므로 확인용으로 쓸 수 있다.","sentences":[3,5]},{"step":"오답 설계","text":"①④는 1·2번의 옛 관행(빨리 자라는 나무)으로, 같은 '선택 행위'라 그럴듯하지만 거리를 휑하게 만들지 않는다 — 비판 내용과 반대다. ③⑤는 3번의 피해 묘사에서 낱말만 가져와 글에 없는 행위로 만들었다.","sentences":[0,1,2]}]}$vf$::jsonb, p_gold => $vf${"answer":1,"decisive":3,"evidence":[3],"evidenceAlt":[4,5],"rationale":"4번에서 처음 제시된 '오래 살고 바람에 강한 느린 수종을 섞어 심기'가 5번에서 'this practice'로 다시 불리며, 거리가 오래 휑하다는 비판도 느린 성장과 맞물린다.","distractors":[{"choice":0,"design":"reversed","why":"1번의 옛 관행으로, 빨리 자라므로 거리를 휑하게 두지 않는다."},{"choice":2,"design":"distorted","why":"3번 피해 묘사의 낱말을 엮어 글에 없는 행위로 만들었다."},{"choice":3,"design":"reversed","why":"2번의 빠른 성장 효과로, 비판 내용과 정반대다."},{"choice":4,"design":"distorted","why":"3번의 shallow roots 를 빌려 글에 없는 처방으로 바꿨다."}]}$vf$::jsonb, p_annotation_ref => $vf$authored-reference-ref-teach-1.v1$vf$, p_provenance => $vf${"author":"Claude (Claude Code agent, Vocaflow FINAL session)","method":"Vocaflow 자체 창작 — 기출 지문을 옮기거나 고쳐 쓰지 않았다","derivedFrom":[],"createdAt":"2026-10-18","humanGold":"pending — 사람 Gold 확정 전","rights":"pending — 사람 원저작 확인 전","set":"r-reference.v1","item":"ref-teach-1"}$vf$::jsonb);
  v_decision := public.content_ai_decision_record(p_ref => v_ref, p_receipt => v_receipt);
  perform public.authored_ai_qualify(p_ref => v_ref, p_role => $vf$model_explanation$vf$, p_axes => $vf${"A":{"state":"pass"},"B":{"state":"pass"},"C":{"state":"pass"},"D":{"state":"not_applicable"},"E":{"state":"not_applicable"},"F":{"state":"pass"},"G":{"state":"not_applicable"},"H":{"state":"pass"}}$vf$::jsonb, p_annotation_ref => $vf$authored-reference-ref-teach-1.v1$vf$, p_evidence_ids => array['ai_decision:' || v_decision, $vf$ai_receipt:6807473e00f86c456b6500ca8007bc5e497196dc2f1930183d25d6024f5f5ecf$vf$, $vf$js_gold:b801af6f648c3cda69d5d4fbbdf291ba7207f8972a8eec16fe115c3d0e0a249f$vf$, 'rights:first_party_original_declaration', $vf$h_probe:gold_response_graded_correct$vf$]);
end $do$;

