  v_decision := public.content_ai_decision_record(p_ref => v_ref, p_receipt => v_receipt);
  perform public.authored_ai_qualify(p_ref => v_ref, p_role => $vf$delayed_check$vf$, p_axes => $vf${"A":{"state":"pass"},"B":{"state":"pass"},"C":{"state":"pass"},"D":{"state":"not_applicable"},"E":{"state":"pass"},"F":{"state":"pass"},"G":{"state":"not_applicable"},"H":{"state":"pass"}}$vf$::jsonb, p_annotation_ref => $vf$authored-multiword-mw-delayed-1.v1$vf$, p_evidence_ids => array['ai_decision:' || v_decision, $vf$ai_receipt:179725ab501da614cebd6d2076f475b2123829657e194e462fb579a5f49fb5b6$vf$, $vf$js_gold:f7bba14f4d9b18e90b953983b47330649bea8d643dd8ccb0d4ed2faf0ff8dff5$vf$, 'rights:first_party_original_declaration', $vf$h_probe:gold_response_graded_correct$vf$]);
